import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:test/test.dart';
import 'package:veil_core/veil_core.dart';

/// Cross-implementation vectors generated by the web app (app/test/vectors.test.ts).
/// Every deterministic value must match byte-for-byte; every randomized value must
/// decrypt/verify. If this fails, the two apps would not be able to talk.
void main() {
  final v = jsonDecode(File('../../protocol/vectors.json').readAsStringSync()) as Map<String, dynamic>;
  Uint8List b(Object? s) => fromB64u(s as String);

  test('ML-KEM-768 (FIPS 203) matches @noble/post-quantum', () {
    final m = v['mlkem768'];
    final kp = MlKem768.keygen(b(m['seed']));
    expect(toB64u(kp.publicKey), m['pk']);
    expect(toB64u(kp.secretKey), m['sk']);
    final enc = MlKem768.encapsulate(kp.publicKey, b(m['m']));
    expect(toB64u(enc.cipherText), m['ct']);
    expect(toB64u(enc.sharedSecret), m['ss']);
    expect(toB64u(MlKem768.decapsulate(b(m['ct']), kp.secretKey)), m['ss']);
  });

  test('X25519 and Ed25519 match WebCrypto', () async {
    final x = v['x25519'];
    final a = await x25519FromSeed(b(x['privA']));
    expect(toB64u(a.pub), x['pubA']);
    expect(toB64u(await x25519(b(x['privA']), b(x['pubB']))), x['shared']);
    final e = v['ed25519'];
    final id = await Identity.fromSeed(b(e['seed']));
    expect(toB64u(id.pub), e['pub']);
    expect(toB64u(await id.sign(b(e['msg']))), e['sig']); // Ed25519 is deterministic
    expect(await ed25519Verify(b(e['pub']), b(e['sig']), b(e['msg'])), isTrue);
  });

  test('handshake transcript and key schedule', () async {
    final h = v['handshake'];
    final i = HelloI(b(h['helloI']['id']), b(h['helloI']['eph']), b(h['helloI']['kem']), b(h['helloI']['n']));
    final r = HelloR(b(h['helloR']['id']), b(h['helloR']['eph']), b(h['helloR']['ct']), b(h['helloR']['n']));
    final t = await transcriptHash(b(h['fpI']), b(h['fpR']), i, r);
    expect(toB64u(t), h['transcript']);
    expect((await deriveKeyMaterial(b(h['ss']), t)).map(toB64u).toList(), h['keys']);
  });

  test('live KDF chain frames', () async {
    final c = v['chain'];
    final tx = SendChain(b(c['ck']), c['label'] as String);
    final rx = RecvChain(b(c['ck']), c['label'] as String);
    for (var k = 0; k < (c['frames'] as List).length; k++) {
      expect(toB64u(await tx.seal(b(c['plaintexts'][k]))), c['frames'][k]);
      expect(toB64u(await rx.open(b(c['frames'][k]))), c['plaintexts'][k]);
    }
  });

  test('safety numbers', () {
    final s = v['safety'];
    expect(safetyNumber(b(s['a']), b(s['b'])), s['number']);
    expect(safetyNumber(b(s['b']), b(s['a'])), s['number']);
  });

  test('envelopes made by the web app open here', () async {
    final e = v['envelope'];
    expect(toB64u((await openEnvelope(b(e['key']), b(e['envelope'])))!), e['plaintext']);
    expect(await openEnvelope(Uint8List(32), b(e['envelope'])), isNull);
  });

  test('Double Ratchet messages interoperate in both directions', () async {
    final r = v['ratchet'];
    final bob = Ratchet.initBob(b(r['sk']), DhKeyPair(b(r['bob']['pub']), b(r['bob']['pkcs8'])), b(r['ad']));
    for (final m in r['aliceToBob']) {
      expect(utf8.decode(await bob.decrypt(b(m['ct']))), m['pt']);
    }
    // Alice's state serialised by the web app, restored here, decrypts Bob's replies.
    final alice = Ratchet.fromJson((r['aliceStateAfterSending'] as Map).cast());
    for (final m in r['bobToAlice']) {
      expect(utf8.decode(await alice.decrypt(b(m['ct']))), m['pt']);
    }
  });

  test('invite links and sealed join notes', () async {
    final iv = v['invite'];
    final inv = decodeInvite(iv['code'] as String);
    expect(inv.toJson(), iv['invite']);
    expect(encodeInvite(inv), startsWith('VEIL3I.'));
    final secret = InviteSecret.fromJson((iv['secret'] as Map).cast());
    final opened = await openJoin(secret, b(iv['joinEnvelope']));
    expect(opened, isNotNull);
    expect(opened!.note.name, 'Bob');
    expect(toB64u(opened.chan), iv['chan']);
    // And a join sealed here opens with the same secret.
    final again = await sealJoin(inv, opened.note);
    expect((await openJoin(secret, again.envelope))?.note.id, opened.note.id);
  });

  test('Nostr gift wraps verify across implementations', () async {
    final ev = (v['nostr']['event'] as Map).cast<String, Object?>();
    expect(await verifyEvent(ev), isTrue);
    expect(await verifyEvent({...ev, 'content': 'tampered'}), isFalse);
    final mine = await wrapEvent('ef' * 32, 'Y2lwaGVydGV4dA', 3600);
    expect(await verifyEvent(mine), isTrue);
  });

  test('one-time signaling codes', () {
    final s = v['signal'];
    final d = decodeSignal(s['code'] as String);
    expect(d.toJson(), s['decoded']);
    expect(decodeSignal(encodeSignal(d)).toJson(), s['decoded']);
    expect(sdpFingerprint(d.sdp), 'sha-256 AA:BB');
  });

  test('backups from the web app restore here (and wrong passphrases fail)', () async {
    final bk = v['backup'];
    final entries = await readBackup(b(bk['file']), bk['passphrase'] as String).toList();
    expect((entries[0] as JsonEntry).d, bk['profile']);
    final chunk = entries[1] as ChunkEntry;
    expect(chunk.fileId, bk['chunk']['fileId']);
    expect(toB64u(chunk.data), bk['chunk']['data']);
    await expectLater(readBackup(b(bk['file']), 'wrong wrong wrong').toList(), throwsA(isA<BackupError>().having((e) => e.code, 'code', BackupErrorCode.wrongPassphrase)));
  });
}
